#!/usr/bin/env python3
"""Build the solver-independent EVRP instance from accepted R05-R14 artifacts."""
from __future__ import annotations
import argparse, csv, hashlib, json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
PAYLOAD_MASS_KG = 1.1
PAYLOAD_MODEL = {'name':'constant_external_observed_median_fixture','mass_kg':PAYLOAD_MASS_KG,'unit':'kg per delivery request','classification':'ASSUMED_FIXTURE_BASELINE_EXTERNAL_PROXY','source':'Dalla Chiara et al. (2020), median observed delivery weight 1.1 kg','transformation':'m_i = 1.1 kg for every selected customer; q_i remains 1 delivery request/customer; no q-to-kg conversion','random_seed':'not_applicable_constant'}
def sha(p: Path) -> str:
    h=hashlib.sha256(); h.update(p.read_bytes()); return h.hexdigest()
def load_csv(p):
    with p.open(newline='', encoding='utf-8') as f: return list(csv.DictReader(f))
def load_json(p): return json.loads(p.read_text(encoding='utf-8'))
def ref(path, classification, unit, transformation='', assumption_reason=''):
    p=ROOT/path if not path.is_absolute() else path
    return {'path':str(path),'sha256':sha(p),'classification':classification,'unit':unit,'transformation':transformation,'assumption_reason':assumption_reason}

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--output-dir',required=True); ap.add_argument('--r09-dir',required=True); ap.add_argument('--r16-dir',required=True); ap.add_argument('--instance-id',required=True); a=ap.parse_args(); out=Path(a.output_dir); out.mkdir(parents=True,exist_ok=True)
    base=Path('reproducibility/outputs/traffic_simulation/demand')
    r05=base/'evrp_r05_pps_sampling/20260909_r05_pps_n10_seed20260909_final'; r06=base/'evrp_r06_customer_demand/20260909_r06_customer_demand_final'; r07=base/'evrp_r07_time_window/20260909_r07_time_window_fixture_n10_v2'; r08=base/'evrp_r08_service_time/20260909_r08_service_time_fixture_n10_final'; r09=Path(a.r09_dir); r10=base/'evrp_r10_ev/20260909_r10_ev_fixture_n10_soc_full_v2'; r11=base/'evrp_r11_charging/20260909_r11_ota_primary_station_revision_model_access'; r12=base/'evrp_r12_routing/20260909_r12_routing_spec_fixture_n10_v18_geometry_reaccepted'; r13=base/'evrp_r13_routing/20260909_r13_routing_fixture_n10_v18_geometry_reaccepted'; r14=base/'evrp_r14_routing_validation/20260909_r14_routing_validation_fixture_n10_v18_geometry_reaccepted'; r16=Path(a.r16_dir)
    customer=load_csv(r06/'customer_demand.csv'); tw=load_csv(r07/'customer_time_windows.csv'); st=load_csv(r08/'customer_service_times.csv'); ep=load_csv(r12/'endpoint_manifest.csv'); od=load_csv(r12/'od_manifest.csv'); routing=load_csv(r13/'routing_arcs.csv'); depot=load_csv(r09/'depot_definition.csv')[0]; vehicle=load_csv(r10/'vehicle_definition.csv')[0]; station=load_csv(r11/'station_catalog.csv')[0]
    endpoints={x['endpoint_id']:x for x in ep}; cust_ids=[x['stop_id'] for x in customer]; assert len(cust_ids)==10 and len(set(cust_ids))==10
    assert [x['stop_id'] for x in tw]==cust_ids and [x['stop_id'] for x in st]==cust_ids
    assert len(ep)==12 and len(od)==132 and len(routing)==132
    node_order=['DEP_006']+cust_ids+['OTA_KEIHIN_TRUCK_TERMINAL_A']; index={x:i for i,x in enumerate(node_order)}
    source_hashes={
      'r05_customer_ids':ref(r05/'customer_ids.csv','COMPUTED','identifier','R05 PPS without replacement output'),
      'r05_manifest':ref(r05/'sampling_manifest.json','COMPUTED','metadata','R05 sampling provenance'),
      'r06_customer_demand':ref(r06/'customer_demand.csv','ASSUMED/COMPUTED','q_i and w_i','R06 q_i=1 baseline; retain R04 w_i'),
      'r07_time_windows':ref(r07/'customer_time_windows.csv','SYNTHETIC_CALIBRATED','hours','R07 service-start interval'),
      'r08_service_times':ref(r08/'customer_service_times.csv','ASSUMED','minutes/customer','R08 fixed baseline'),
      'r09_depot':ref(r09/'depot_definition.csv','PROXY','coordinates and edge mapping','R09 selected proxy'),
      'r10_vehicle':ref(r10/'vehicle_definition.csv','OBSERVED/ASSUMED/COMPUTED','vehicle parameters','R10 EV specification and SOC assumptions'),
      'r11_station':ref(r11/'station_catalog.csv','PUBLIC_SPECIFICATION/ASSUMED/COMPUTED','station parameters','R11 primary specification and modeling access assumption'),
      'r12_endpoint_manifest':ref(r12/'endpoint_manifest.csv','COMPUTED','endpoint mapping','V18 endpoint authority'),
      'r12_od_manifest':ref(r12/'od_manifest.csv','COMPUTED','directed OD','V18 required OD set'),
      'r13_routing':ref(r13/'routing_arcs.csv','COMPUTED','m and s','accepted V18 routing output'),
      'r14_validation':ref(r14/'r14_validation_report.json','COMPUTED','validation status','independent V18 validation PASS'),
      'r14_geometry_validation':ref(r14/'v18_route_geometry_length_validation.json','COMPUTED','validation status','V18 route geometry/length validation PASS'),
    }
    nodes=[]
    for eid in node_order:
        x=endpoints[eid]; nodes.append({'solver_index':index[eid],'endpoint_id':eid,'node_type':x['endpoint_type'],'latitude':float(x['latitude']),'longitude':float(x['longitude']),'mapped_edge_id':x['mapped_edge_id'],'edge_offset_m':float(x['edge_offset_m']),'mapping_distance_m':float(x['mapping_distance_m']),'vehicle_class':'delivery','source_artifact':x['source_artifact']})
    cust_by={x['stop_id']:x for x in customer}; tw_by={x['stop_id']:x for x in tw}; st_by={x['stop_id']:x for x in st}
    customers=[]
    for cid in cust_ids:
        q=cust_by[cid]; w=tw_by[cid]; s=st_by[cid]
        customers.append({'customer_id':cid,'solver_index':index[cid],'customer_order':int(q['customer_order']),'building_id':q['building_id'],'customer_selected':q['customer_selected'],'sampling_weight':{'value':float(q['w_i']),'unit':q['w_i_unit'],'classification':q['w_i_classification']},'demand':{'q_i':float(q['q_i']),'delivery_request_count':float(q['q_i']),'unit':q['q_i_unit'],'classification':q['q_i_classification'],'source':q['q_i_source'],'transformation':q['q_i_transformation'],'assumption_reason':q['q_i_assumption_reason']},'payload':{'m_i':PAYLOAD_MASS_KG,'payload_mass_kg':PAYLOAD_MASS_KG,**PAYLOAD_MODEL},'time_window':{'e_i':float(w['e_i']),'l_i':float(w['l_i']),'unit':w['time_unit'],'time_origin':w['time_origin'],'classification':w['classification'],'source':w['source'],'transformation':w['transformation'],'assumption_reason':w['assumption_reason']},'service_time':{'value':float(s['s_i']),'unit':s['s_i_unit'],'classification':s['s_i_classification'],'source':s['s_i_source'],'transformation':s['s_i_transformation'],'assumption_reason':s['s_i_assumption_reason']}})
    route_rows=[]
    for x in routing:
        route_rows.append({'origin_id':x['origin_id'],'destination_id':x['destination_id'],'origin_index':index[x['origin_id']],'destination_index':index[x['destination_id']],'origin_type':x['origin_type'],'destination_type':x['destination_type'],'origin_edge':x['origin_edge'],'destination_edge':x['destination_edge'],'origin_offset_m':float(x['origin_offset_m']),'destination_offset_m':float(x['destination_offset_m']),'reachable':x['reachable']=='True','distance_m':None if x['distance_m']=='' else float(x['distance_m']),'travel_time_s':None if x['travel_time_s']=='' else float(x['travel_time_s']),'path_edge_sequence':json.loads(x['path_edge_sequence']) if x['path_edge_sequence'] else None,'routing_objective':x['routing_objective'],'vehicle_class':x['vehicle_class'],'network_hash':x['network_hash']})
    instance={'instance_id':'evrp_fixture_n10_v18_common_20260909','schema_version':'evrp-common-instance-v1','fixture_or_production':{'value':'fixture','n':10,'is_production_problem_size':False,'production_n':'UNADOPTED until QUBO encoding/logical-qubit/resource relation is fixed'},'node_order':nodes,'customer_order':cust_ids,'vehicle_order':[vehicle['vehicle_id']],'customers':customers,'depot':{'depot_id':depot['depot_id'],'facility_name':depot['facility_name'],'classification':depot['classification'],'proxy_or_observed':depot['proxy_or_observed'],'latitude':float(depot['latitude']),'longitude':float(depot['longitude']),'mapped_edge_id':depot['mapped_sumo_edge_id'],'edge_offset_m':float(depot['edge_offset_m']),'mapping_distance_m':float(depot['mapping_distance_m'])},'vehicles':[{'vehicle_id':vehicle['vehicle_id'],'vehicle_class':vehicle['vehicle_class'],'solver_index':0,'fleet_size':int(vehicle['fleet_size']),'payload_capacity_kg':float(vehicle['payload_capacity_kg']),'battery_capacity_kwh':float(vehicle['battery_capacity_kwh']),'operational_available_energy_kwh':float(vehicle['operational_available_energy_kwh']),'energy_consumption_kwh_per_km':float(vehicle['energy_consumption_kwh_per_km']),'initial_soc':float(vehicle['initial_soc']),'minimum_soc':float(vehicle['minimum_soc']),'depot_return_minimum_soc_applies':vehicle['depot_return_minimum_soc_applies']=='True','maximum_operating_time_enabled':vehicle['maximum_operating_time_enabled']=='True','classification':{'payload':vehicle['payload_classification'],'battery':vehicle['battery_classification'],'energy':'COMPUTED','initial_soc':vehicle['initial_soc_classification'],'minimum_soc':vehicle['minimum_soc_classification']},'energy_formula':vehicle['energy_formula']}],'charging_stations':[{'station_id':station['station_id'],'station_name':station['station_name'],'latitude':float(station['latitude']),'longitude':float(station['longitude']),'connector_type':station['connector_type'],'rated_power_kw':float(station['rated_power_kw']),'effective_charging_power_kw':70.0,'max_session_duration_min':float(station['max_session_duration_min']),'usage_hours':station['usage_hours'],'mapped_edge_id':station['mapped_edge_id'],'edge_offset_m':float(station['edge_offset_m']),'mapping_distance_m':float(station['mapping_distance_m']),'external_operator_access':'ASSUMED_AVAILABLE_FOR_MODELING','external_operator_access_classification':'ASSUMED','charging_time_formula':'min((delta_E_kWh / min(P_station_kW, P_vehicle_kW))*60, max_session_duration_min)','charging_efficiency_assumption':1.0}],'routing':{'network_authority':'CURRENT-NETWORK-COMPLETION-AUTHORITY-V18-GEOMETRY-REACCEPTED','network_hash':routing[0]['network_hash'],'vehicle_class':'delivery','routing_objective':'travel_time_minimizing','distance_unit':'m','travel_time_unit':'s','reachability_unit':'boolean','unreachable_semantics':'reachable=false; distance/time=null','required_od_count':len(route_rows),'arcs':route_rows},'source_hashes':source_hashes,'random_seeds':{'R05':20260909,'R07':20260909,'R06':'not_applicable_deterministic','R08':'not_applicable_deterministic','R09':'not_applicable_deterministic','R10':'not_applicable_deterministic','R11':'not_applicable','R12':'not_applicable','R13':'deterministic_tie_break_by_edge_id'},'constraint_version':'R16_NOT_STARTED_REFERENCE_EV_RP_COMMON_HARD_CONSTRAINTS','objective_priority':'R17_NOT_STARTED_REFERENCE_LEXICOGRAPHIC_MAX_CUSTOMERS','units':{'coordinates':'WGS84 degrees','demand':'delivery requests/customer','time_window':'hours from local_day_start_00:00','service_time':'minutes/customer','distance':'m','travel_time':'s','payload':'kg','battery':'kWh','energy_rate':'kWh/km','SOC':'ratio 0-1','charging_power':'kW','session_duration':'minutes'}}
    (out/'common_instance.json').write_text(json.dumps(instance,ensure_ascii=False,indent=2)+'\n'); (out/'node_index_mapping.csv').write_text('solver_index,endpoint_id,node_type\n'+'\n'.join(f"{x['solver_index']},{x['endpoint_id']},{x['node_type']}" for x in nodes)+'\n'); (out/'provenance_ledger.json').write_text(json.dumps(source_hashes,ensure_ascii=False,indent=2)+'\n'); (out/'r15_config.json').write_text(json.dumps({'instance_id':instance['instance_id'],'schema_version':instance['schema_version'],'source_run_ids':{'R05':'20260909_r05_pps_n10_seed20260909_final','R06':'20260909_r06_customer_demand_final','R07':'20260909_r07_time_window_fixture_n10_v2','R08':'20260909_r08_service_time_fixture_n10_final','R09':'20260909_r09_depot_fixture_n10_v2','R10':'20260909_r10_ev_fixture_n10_soc_full_v2','R11':'20260909_r11_ota_primary_station_revision_model_access','R12':'20260909_r12_routing_spec_fixture_n10_v18_geometry_reaccepted','R13':'20260909_r13_routing_fixture_n10_v18_geometry_reaccepted','R14':'20260909_r14_routing_validation_fixture_n10_v18_geometry_reaccepted'}},ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'instance_id':instance['instance_id'],'customers':10,'nodes':len(nodes),'od':len(route_rows),'output_dir':str(out)},ensure_ascii=False))
if __name__=='__main__': main()
